using System.Globalization;
using System.Text;
using Kosher.Zmanim.Internal;
using Kosher.Zmanim.Util;
using Xunit;

namespace Kosher.Zmanim.Tests.Golden;

/// <summary>
/// Cross-checks this port against values generated by KosherJava 3.1.0 itself (see <c>tools/golden/GoldenGenerator.java</c>):
/// every <em>zman</em> of <see cref="ComprehensiveZmanimCalendar"/> with the NOAA calculator, the core astronomical times with
/// the SPA, Meeus and SunTimes calculators, and the raw calculator output (UTC rise/set hours at many zeniths, solar
/// elevation and azimuth), for 12 locations (both hemispheres, the equator, the dateline, the Arctic, horizon elevations)
/// on ~70 dates including DST transitions, solstices and dates from 1900 to 2099.
/// </summary>
/// <remarks>
/// <c>java.time</c> has nanosecond resolution and .NET has 100 nanosecond ticks, and the trigonometric functions of the
/// two runtimes may differ in the last bit. Times therefore must match to within <see cref="ToleranceNanos"/> (two
/// microseconds). The largest difference measured over the ~500,000 values is 1.3 microseconds; the median is under 100
/// nanoseconds, i.e. the values agree to the 100 ns tick.
/// </remarks>
public class GoldenZmanimTests
{
    /// <summary>Maximum allowed difference between a KosherJava time and this port's time, in nanoseconds.</summary>
    public const long ToleranceNanos = 2_000;

    /// <summary>Maximum allowed difference of raw calculator results (hours or degrees).</summary>
    public const double ToleranceRaw = 1e-9;

    private static readonly Dictionary<string, GeoLocation> Locations = new()
    {
        ["lakewood"] = new GeoLocation("lakewood", 40.0721087, -74.2400243, 15, Tz("America/New_York")),
        ["woodcliff"] = new GeoLocation("woodcliff", 41.1181036, -74.0840691, 167, Tz("America/New_York")),
        ["la"] = new GeoLocation("la", 34.0201613, -118.6919095, 71, Tz("America/Los_Angeles")),
        ["jerusalem"] = new GeoLocation("jerusalem", 31.7962994, 35.1053185, 754, Tz("Asia/Jerusalem")),
        ["norway"] = new GeoLocation("norway", 70.1498248, 9.1456867, 0, Tz("Europe/Oslo")),
        ["sydney"] = new GeoLocation("sydney", -33.8688, 151.2093, 58, Tz("Australia/Sydney")),
        ["macapa"] = new GeoLocation("macapa", 0.0349, -51.0694, 15, Tz("America/Belem")),
        ["suva"] = new GeoLocation("suva", -18.1416, 178.4419, 6, Tz("Pacific/Fiji")),
        ["ushuaia"] = new GeoLocation("ushuaia", -54.8019, -68.3030, 23, Tz("America/Argentina/Ushuaia")),
        ["apia"] = new GeoLocation("apia", -13.8333, -171.75, 2, Tz("Pacific/Apia")),
        ["horizon"] = new GeoLocation("horizon", 31.7683, 35.2137, 800, 650, 720, Tz("Asia/Jerusalem")),
        ["utc"] = new GeoLocation("utc", 51.4772, 0, 0, TimeZoneInfo.Utc),
    };

    private static TimeZoneInfo Tz(string id) => TimeZoneInfo.FindSystemTimeZoneById(id);

    private static AstronomicalCalculator Calculator(string name) => name switch
    {
        "SPA" => new SPACalculator(),
        "Meeus" => new MeeusCalculator(),
#pragma warning disable CS0618 // SunTimesCalculator is obsolete, but still part of the API and verified here
        "SunTimes" => new SunTimesCalculator(),
#pragma warning restore CS0618
        _ => new NOAACalculator(),
    };

    [Fact]
    public void AllZmanimMatchKosherJava()
    {
        var failures = new List<string>();
        string[]? zHeader = null, bHeader = null;
        var getters = new Dictionary<string, Func<object, object?>>();
        long compared = 0, exact = 0, maxDiff = 0, skippedRows = 0;
        foreach (string line in JavaApi.ReadLines("zmanim.tsv.gz"))
        {
            string[] f = line.Split('\t');
            if (f[0] == "#Z")
            {
                zHeader = f;
                continue;
            }
            if (f[0] == "#B")
            {
                bHeader = f;
                continue;
            }
            if (f[0] != "Z" && f[0] != "B")
            {
                continue;
            }
            string[] header = f[0] == "Z" ? zHeader! : bHeader!;
            GeoLocation geo = Locations[f[1]];
            var date = DateOnly.Parse(f[2], CultureInfo.InvariantCulture);
            var czc = new ComprehensiveZmanimCalendar(geo) { AstronomicalCalculator = Calculator(f[3]) };
            if (f[4] == "1")
            {
                czc.UseElevation = true;
                czc.UseAstronomicalChatzos = false;
                czc.CandleLightingOffset = 40;
                czc.AteretTorahSunsetOffset = 30;
            }
            czc.LocalDate = date;
            // KosherJava uses its own copy of the IANA time zone database, .NET uses the operating system's (the IANA database on
            // Linux and macOS, Windows' own time zone data on Windows). They can disagree on historical rules (on Linux only before
            // 1970), and .NET can't represent the seconds in local mean time offsets such as Jerusalem's +2:20:40 in 1900. A
            // different UTC offset legitimately changes the results, so skip those location/dates.
            // Some zmanim (such as chatzos halayla) also depend on the next day, so both midnights must agree. They are taken the
            // way the library (and java.time's atStartOfDay) does, so a day skipped by the zone, such as Samoa's December 30, 2011,
            // resolves to the first instant after the gap.
            int javaOffsetSeconds = int.Parse(f[5], CultureInfo.InvariantCulture);
            int javaNextOffsetSeconds = int.Parse(f[6], CultureInfo.InvariantCulture);
            TimeSpan dotnetOffset = JavaTime.AtZone(date, TimeOnly.MinValue, geo.TimeZone).Offset;
            TimeSpan dotnetNextOffset = JavaTime.AtZone(date.AddDays(1), TimeOnly.MinValue, geo.TimeZone).Offset;
            if ((int)dotnetOffset.TotalSeconds != javaOffsetSeconds || (int)dotnetNextOffset.TotalSeconds != javaNextOffsetSeconds)
            {
                if (OperatingSystem.IsLinux())
                {
                    Assert.True(date.Year < 1970, $"{f[1]} {f[2]}: time zone offsets {dotnetOffset} / {dotnetNextOffset} differ from Java's {javaOffsetSeconds} / {javaNextOffsetSeconds} s");
                }
                skippedRows++;
                continue;
            }
            for (int i = 7; i < f.Length; i++)
            {
                string method = header[i];
                if (!getters.TryGetValue(method, out var getter))
                {
                    getter = JavaApi.Getter(typeof(ComprehensiveZmanimCalendar), method);
                    getters[method] = getter;
                }
                string context = $"{f[1]} {f[2]} {f[3]} cfg{f[4]} {method}";
                object? actual;
                try
                {
                    actual = getter(czc);
                }
                catch (Exception e)
                {
                    if (!f[i].StartsWith("EX:", StringComparison.Ordinal))
                    {
                        failures.Add($"{context}: threw {e.GetType().Name}: {e.Message}, expected {f[i]}");
                    }
                    else if (!JavaApi.ExceptionType(f[i].Substring(3)).IsInstanceOfType(e))
                    {
                        failures.Add($"{context}: threw {e.GetType().Name}, expected {f[i]}");
                    }
                    continue;
                }
                compared++;
                string expected = f[i];
                if (method == "getCandleLighting" && expected == "null")
                {
                    // KosherJava returns null when candle lighting is before plag hamincha (very short winter days);
                    // Kosher.Zmanim returns plag hamincha instead.
                    int plag = Array.IndexOf(header, "getPlagHaminchaGRA");
                    if (plag > 0)
                    {
                        expected = f[plag];
                    }
                }
                long diff = Compare(expected, actual, geo, context, failures);
                if (diff == 0)
                {
                    exact++;
                }
                maxDiff = Math.Max(maxDiff, diff);
            }
        }
        Assert.True(compared > 100_000, $"only {compared} values compared");
        Assert.True(skippedRows < 300, $"{skippedRows} rows skipped for time zone differences");
        Assert.True(failures.Count == 0, Report(failures, compared, exact, maxDiff));
    }

    private static long Compare(string expected, object? actual, GeoLocation geo, string context, List<string> failures)
    {
        if (expected == "null")
        {
            if (actual != null)
            {
                failures.Add($"{context}: expected null, was {actual}");
            }
            return 0;
        }
        if (actual == null)
        {
            failures.Add($"{context}: expected {expected}, was null");
            return 0;
        }
        long nanos = long.Parse(expected.AsSpan(1), CultureInfo.InvariantCulture);
        long diff;
        if (expected[0] == 'I')
        {
            var time = (DateTimeOffset)actual;
            diff = Math.Abs(JavaApi.EpochNanos(time) - nanos);
            TimeSpan zoneOffset = geo.TimeZone.GetUtcOffset(time);
            if (time.Offset != zoneOffset)
            {
                failures.Add($"{context}: offset {time.Offset} is not the zone offset {zoneOffset}");
            }
        }
        else
        {
            var duration = (TimeSpan)actual;
            diff = Math.Abs(duration.Ticks * 100 - nanos);
        }
        if (diff > ToleranceNanos)
        {
            failures.Add($"{context}: expected {expected}, was {actual} (diff {diff} ns)");
        }
        return diff;
    }

    [Fact]
    public void RawCalculatorResultsMatchKosherJava()
    {
        double[] zeniths = { 90, 90.833, 96, 102, 108, 106.1, 109.8, 98.5, 93.7, 84, 80 };
        var failures = new List<string>();
        long compared = 0;
        double maxDiff = 0;
        foreach (string line in JavaApi.ReadLines("zmanim.tsv.gz"))
        {
            string[] f = line.Split('\t');
            if (f[0] != "C")
            {
                continue;
            }
            GeoLocation geo = Locations[f[1]];
            var date = DateOnly.Parse(f[2], CultureInfo.InvariantCulture);
            AstronomicalCalculator c = Calculator(f[3]);
            int i = 4;
            void Check(string what, double actual)
            {
                double expected = double.Parse(f[i++], CultureInfo.InvariantCulture);
                compared++;
                if (double.IsNaN(expected) || double.IsNaN(actual))
                {
                    if (double.IsNaN(expected) != double.IsNaN(actual))
                    {
                        failures.Add($"{f[1]} {f[2]} {f[3]} {what}: expected {expected}, was {actual}");
                    }
                    return;
                }
                double diff = Math.Abs(expected - actual);
                // azimuths can wrap around 0/360
                if (what.StartsWith("Azimuth", StringComparison.Ordinal) && diff > 359)
                {
                    diff = 360 - diff;
                }
                maxDiff = Math.Max(maxDiff, diff);
                if (diff > ToleranceRaw)
                {
                    failures.Add($"{f[1]} {f[2]} {f[3]} {what}: expected {expected:R}, was {actual:R} (diff {diff:E2})");
                }
            }
            foreach (double z in zeniths)
            {
                foreach (bool adj in new[] { false, true })
                {
                    Check($"UTCSunrise {z} {adj}", c.GetUTCSunrise(date, geo, z, adj));
                    Check($"UTCSunset {z} {adj}", c.GetUTCSunset(date, geo, z, adj));
                }
            }
            Check("UTCNoon", c.GetUTCNoon(date, geo));
            Check("UTCMidnight", c.GetUTCMidnight(date, geo));
            if (f[3] != "SunTimes")
            {
                DateTimeOffset noonish = new DateTimeOffset(date.ToDateTime(new TimeOnly(12, 0)), TimeSpan.Zero)
                    .AddSeconds(-(long)(geo.Longitude * 240));
                for (int h = -9; h <= 9; h += 3)
                {
                    DateTimeOffset at = noonish.AddSeconds(h * 3600L + 1234);
                    Check($"Elevation {h}", c.GetSolarElevation(at, geo));
                    Check($"Azimuth {h}", c.GetSolarAzimuth(at, geo));
                }
                Check("AzimuthTime 90", c.GetTimeAtAzimuth(date, geo, 90));
                Check("AzimuthTime 270", c.GetTimeAtAzimuth(date, geo, 270));
            }
        }
        Assert.True(compared > 50_000, $"only {compared} values compared");
        Assert.True(failures.Count == 0, $"{failures.Count} of {compared} raw values differ (max diff {maxDiff:E2}):\n"
            + string.Join("\n", failures.Take(40)));
    }

    private static string Report(List<string> failures, long compared, long exact, long maxDiff)
    {
        var sb = new StringBuilder();
        sb.Append(failures.Count).Append(" failures of ").Append(compared).Append(" values (").Append(exact)
            .Append(" exact, max diff ").Append(maxDiff).Append(" ns):\n");
        foreach (string failure in failures.Take(60))
        {
            sb.Append(failure).Append('\n');
        }
        return sb.ToString();
    }
}
